waves.point_eqs_eel:
r = abs (sin (frame /38));
g = 0.5*abs (cos (frame /45));
b = 0.5*abs (sin (frame / 133));
a = 0.3;
t02 = t02 + q1/10;
ratio = sin (frame/49);

ampl = 0.01+0.4*sqr(sin ((frame ) / 18)* cos (frame / 123));

x1 = (r-0.5)/15 +0.5 + ampl* sin (sample*6.28);
y1 = (b-0.5)/15+0.5 + ampl* cos (sample*6.28);

x =  x1+1*0.2*(ampl+ratio )*sin ( sample*6.28 * ratio*7.3);
y =  y1+1*0.2*(ampl+ratio )*cos ( sample*6.28*6);

preset.frame_eqs_eel:
dec_med = pow (0.9, 30/fps);
dec_slow = pow (0.995, 30/fps);
beat = max (max (bass, mid), treb); 
avg = avg*dec_slow + beat*(1-dec_slow);
is_beat = above(beat, .5+avg+peak) * above (time, t0+.2);
t0 = is_beat*time + (1-is_beat)*t0;
peak = is_beat * beat + (1-is_beat)*peak*dec_med;
index = (index + is_beat) * below (index,4);

q20 = avg;
q21 = beat;
q22 = peak;
q23 = index;


myvol = (bass_att+treb_att+mid_att);
myvol_s = myvol_s + above (myvol, myvol_s);
myvol_s = 0.995*myvol_s + 0.005*myvol;
myvol_s = min (myvol_s,15);
q1 = (myvol_s + 2*(bass+treb))/1000 * 30/fps;
dir = dir * 0.99 + .01*(index-1);
dir = .5*(index-2);
//q1 = q1 * dir;

q2=myvol_s/3+1;
rot = 0.3*sin(time/4);

